from urllib.parse import urlparse


def validate_url_field(config, field):
    """Validate that a URL field is present, non-empty, and structurally valid.

    Returns 0 if valid, 1 if invalid.
    """
    value = config.get(field)
    if not value:
        return 1
    parsed = urlparse(value)
    if not parsed.scheme or not parsed.netloc:
        return 1
    return 0


def validate(config, service):
    """Validate the service URL field for the given service.

    The expected field name follows the convention '{service}_service_url'.
    """
    field = f"{service}_service_url"
    return validate_url_field(config, field)

